/**
 * Customizable multi-sheet Excel export: a Summary dashboard sheet (metrics +
 * per-coach breakdown + optional AI notes) plus a Delegates detail sheet with
 * only the columns/rows requested.
 *
 * Three surfaces:
 *   POST /api/trips/:id/export            → build + stream the .xlsx (filtered)
 *   GET  /api/trips/:id/export            → same, unfiltered (back-compat)
 *   POST /api/trips/:id/export/ai-filter  → natural-language → structured filter
 *
 * The AI layer is deliberately BOUNDED: it only turns plain language into the
 * same structured filter object the checkboxes produce, which the UI then shows
 * and lets the user edit. The model never sees or writes delegate data, and an
 * unreachable model must degrade gracefully — checkboxes still work, and a
 * missing AI summary is omitted rather than failing the export.
 *
 * Mirrors insights.js's provider strategy (local Ollama first, then Anthropic,
 * then a clear "not configured"), none of which can crash startup.
 */

import { Router } from "express";
import ExcelJS from "exceljs";
import { getTrip, getDashboard, getDelegates, resolveTripUuid, getVisibleCoachIds } from "../../data.js";
import { all } from "../../db/connection.js";
import { requireAuth, requirePermission } from "../../lib/auth.js";

const router = Router();
const wrap = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

/* ---- shared vocabulary --------------------------------------------------- */
// PRESENT is the legacy alias for ARRIVED. Every status comparison here must
// normalize it, or counts differ by which check-in route wrote the row.
const normStatus = (s) => (s === "PRESENT" ? "ARRIVED" : s);
const STATUS_ORDER = ["UNASSIGNED", "ASSIGNED", "ARRIVED", "LATE", "MISSING"];
const UNASSIGNED_KEY = "__unassigned";

/* ---- export-content translation (English / Simplified Chinese) -----------
 * Generated server-side, so it can't reuse the frontend's i18n.jsx. Covers only
 * strings that appear IN the workbook. `lang` is an explicit per-export choice
 * (ExportModal.jsx), NOT the staff member's UI language — a coordinator may
 * work in English but hand off a Chinese report. */
const T = {
  en: {
    sheetSummary: "Summary", sheetDelegates: "Delegates", sheetCheckpoints: "Checkpoint history", sheetCharts: "Charts",
    title: (name) => `${name} — Attendance Export`,
    generated: (when, filters) => `Generated ${when} · Filters — ${filters}`,
    keyMetrics: "KEY METRICS", total: "Total", arrived: "Arrived", missing: "Missing", late: "Late", assigned: "Assigned",
    unassignedNoCoach: "Unassigned (no coach)",
    coachBreakdown: "COACH BREAKDOWN", boarded: "Boarded", pctBoarded: "% Boarded",
    unassignedGroup: "Unassigned",
    aiSummary: "AI SUMMARY",
    noMatch: "No delegates match the selected filters.",
    filterStatus: "Status", filterCoach: "Coach", filterVip: "VIP only", filterNone: "None (all delegates)",
    status: { UNASSIGNED: "Unassigned", ASSIGNED: "Assigned", ARRIVED: "Arrived", LATE: "Late", MISSING: "Missing" },
    columns: {
      name: "Name", coach: "Coach", status: "Status", vip: "VIP", company: "Company", role: "Role",
      industry: "Industry", email: "Email", phone: "Phone", nationality: "Nationality",
      passportNumber: "Passport", lastSeen: "Last seen", lastLocation: "Last location", createdAt: "Uploaded",
    },
    checkpointColumns: {
      name: "Name", coach: "Coach", day: "Day", checkpoint: "Checkpoint", scheduledTime: "Scheduled time",
      status: "Status", scannedBy: "Scanned by", updatedAt: "Updated",
    },
    noCheckpoints: "No checkpoint scans recorded for the selected delegates.",
  },
  zh: {
    sheetSummary: "摘要", sheetDelegates: "代表名单", sheetCheckpoints: "打卡记录", sheetCharts: "图表",
    title: (name) => `${name} — 出席情况导出`,
    generated: (when, filters) => `生成于 ${when} · 筛选条件 — ${filters}`,
    keyMetrics: "关键指标", total: "总数", arrived: "已抵达", missing: "缺席", late: "迟到", assigned: "已分配",
    unassignedNoCoach: "未分配（无车辆）",
    coachBreakdown: "各车辆情况", boarded: "已登车", pctBoarded: "登车率",
    unassignedGroup: "未分配",
    aiSummary: "AI 摘要",
    noMatch: "没有符合所选筛选条件的代表。",
    filterStatus: "状态", filterCoach: "车辆", filterVip: "仅限贵宾", filterNone: "无（全部代表）",
    status: { UNASSIGNED: "未分配", ASSIGNED: "已分配", ARRIVED: "已抵达", LATE: "迟到", MISSING: "缺席" },
    columns: {
      name: "姓名", coach: "车辆", status: "状态", vip: "贵宾", company: "公司", role: "职位",
      industry: "行业", email: "电子邮箱", phone: "电话", nationality: "国籍",
      passportNumber: "护照号码", lastSeen: "最后出现", lastLocation: "最后位置", createdAt: "上传时间",
    },
    checkpointColumns: {
      name: "姓名", coach: "车辆", day: "天数", checkpoint: "打卡点", scheduledTime: "预定时间",
      status: "状态", scannedBy: "扫描人", updatedAt: "更新时间",
    },
    noCheckpoints: "所选代表没有打卡记录。",
  },
};
const tt = (lang) => T[lang === "zh" ? "zh" : "en"];

// Every column the detail sheet can render. `get` pulls the display value;
// ctx carries {coachName, tt} so Status/VIP render in the requested language.
// The English `label` is ONLY /export/options metadata and the fallback key —
// the real header text comes from tt(lang).columns[key] in buildWorkbook.
const ALL_COLUMNS = [
  { key: "name", label: "Name", width: 22, get: (d) => d.name },
  { key: "coach", label: "Coach", width: 20, get: (d, ctx) => ctx.coachName(d.coachId) },
  { key: "status", label: "Status", width: 13, get: (d, ctx) => ctx.tt.status[normStatus(d.status)] || d.status },
  { key: "vip", label: "VIP", width: 7, get: (d, ctx) => (d.vip ? ctx.tt.columns.vip : "") },
  { key: "company", label: "Company", width: 24, get: (d) => d.company || "" },
  { key: "role", label: "Role", width: 18, get: (d) => d.role || "" },
  { key: "industry", label: "Industry", width: 18, get: (d) => d.industry || "" },
  { key: "email", label: "Email", width: 24, get: (d) => d.email || "" },
  { key: "phone", label: "Phone", width: 16, get: (d) => d.phone || "" },
  { key: "nationality", label: "Nationality", width: 14, get: (d) => d.nationality || "" },
  { key: "passportNumber", label: "Passport", width: 16, get: (d) => d.passportNumber || "" },
  // Free-text field: staff sometimes type the label into the value, so strip a
  // redundant leading "Last seen · ". Matches only that exact phrase, leaving
  // other text ("Reset · 14:02", a place name) untouched.
  { key: "lastSeen", label: "Last seen", width: 22, get: (d) => (d.lastSeen || "").replace(/^last seen\s*[·:-]?\s*/i, "") },
  { key: "lastLocation", label: "Last location", width: 24, get: (d) => d.lastLocation || "" },
  { key: "createdAt", label: "Uploaded", width: 18, get: (d) => fmtDate(d.createdAt) },
];
const DEFAULT_COLUMNS = ["name", "coach", "status", "vip", "company", "lastSeen", "createdAt"];

const STATUS_FILL = {
  ARRIVED: "FFE7F5EC", MISSING: "FFFDECEC", UNASSIGNED: "FFFDF3E3", ASSIGNED: "FFE7EEFB", LATE: "FFFCEEDB",
};
const BORDER = { style: "thin", color: { argb: "FFE5E7EB" } };
const THIN_BORDER = { top: BORDER, left: BORDER, bottom: BORDER, right: BORDER };
const BRAND = "FFE1232A";

function fmtDate(v) {
  if (!v) return "";
  const d = new Date(v);
  return isNaN(d) ? "" : d.toLocaleString("en-GB", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" });
}

/* ---- filtering ----------------------------------------------------------- */
// An empty/missing array means "no constraint on that dimension", so an empty
// filter object exports everything (matching the old unfiltered behaviour).
function makeCoachName(coaches, lang) {
  const fallback = tt(lang).unassignedGroup;
  return (id) => {
    if (!id) return fallback;
    const c = coaches.find((x) => x.id === id);
    return c ? [c.name, c.city].filter(Boolean).join(" · ") : fallback;
  };
}

function passesFilter(d, filters) {
  const st = normStatus(d.status);
  if (Array.isArray(filters.statuses) && filters.statuses.length && !filters.statuses.includes(st)) return false;
  if (Array.isArray(filters.coachIds) && filters.coachIds.length) {
    const cid = d.coachId || UNASSIGNED_KEY;
    if (!filters.coachIds.includes(cid)) return false;
  }
  if (filters.vipOnly && !d.vip) return false;
  return true;
}

function describeFilters(filters, coaches, lang) {
  const L = tt(lang);
  const parts = [];
  if (filters.statuses?.length) parts.push(`${L.filterStatus}: ${filters.statuses.map((s) => L.status[s] || s).join(", ")}`);
  if (filters.coachIds?.length) {
    const coachName = makeCoachName(coaches, lang);
    parts.push(`${L.filterCoach}: ${filters.coachIds.map((id) => (id === UNASSIGNED_KEY ? L.unassignedGroup : coachName(id))).join(", ")}`);
  }
  if (filters.vipOnly) parts.push(L.filterVip);
  return parts.length ? parts.join("  ·  ") : L.filterNone;
}

/* ---- checkpoint history ---------------------------------------------------
 * The export path for routes/checkpoints.js data, previously only viewable one
 * delegate at a time in DelegateTimeline.jsx. Pulls EVERY checkin for the trip
 * in ONE query (not a per-delegate loop) so this stays fast at any roster size.
 * Opt-in, so the default export is unaffected. */
async function loadCheckpointHistory(tripUuid) {
  return all(
    `SELECT cc.delegate_id AS "delegateId", cc.status, cc.method, cc.scanned_by AS "scannedBy",
            cc.updated_at AS "updatedAt", i.title AS "checkpointLabel",
            TO_CHAR(i.start_time, 'HH24:MI') AS "scheduledTime", i.day_number AS "dayNumber"
     FROM checkpoint_checkins cc
     JOIN itinerary_items i ON i.id = cc.itinerary_item_id
     JOIN delegates d ON d.id = cc.delegate_id
     WHERE d.trip_id = $1
     ORDER BY i.day_number, i.sort_order, i.start_time, d.name`,
    [tripUuid]
  );
}

/* ---- workbook builder ---------------------------------------------------- */
function buildWorkbook({ trip, delegates, coaches, filters, columns, aiSummary, checkpointHistory, chartImages, lang }) {
  const L = tt(lang);
  const coachName = makeCoachName(coaches, lang);
  const ctx = { coachName, tt: L };
  const cols = (columns && columns.length ? columns : DEFAULT_COLUMNS)
    .map((k) => ALL_COLUMNS.find((c) => c.key === k))
    .filter(Boolean);

  const wb = new ExcelJS.Workbook();
  wb.creator = "MusterGo";
  wb.created = new Date();

  /* ===== Sheet 1 — Summary dashboard ===== */
  const sum = wb.addWorksheet(L.sheetSummary, { views: [{ showGridLines: false }] });
  sum.columns = [{ width: 26 }, { width: 14 }, { width: 12 }, { width: 12 }, { width: 12 }, { width: 12 }];

  const titleRow = sum.addRow([L.title(trip?.name || "Trip")]);
  sum.mergeCells(titleRow.number, 1, titleRow.number, 6);
  titleRow.getCell(1).font = { size: 15, bold: true };
  const metaRow = sum.addRow([
    `${trip?.dateRange || ""}${trip ? ` · Day ${trip.dayOf} of ${trip.totalDays}` : ""}${trip?.lead ? ` · Lead: ${trip.lead}` : ""}`,
  ]);
  sum.mergeCells(metaRow.number, 1, metaRow.number, 6);
  metaRow.getCell(1).font = { size: 10, color: { argb: "FF6B7280" } };
  const genRow = sum.addRow([L.generated(new Date().toLocaleString("en-GB"), describeFilters(filters, coaches, lang))]);
  sum.mergeCells(genRow.number, 1, genRow.number, 6);
  genRow.getCell(1).font = { size: 9, italic: true, color: { argb: "FF6B7280" } };
  sum.addRow([]);

  // Counts over the FILTERED set, so the summary agrees with the Delegates
  // sheet beside it.
  const counts = { total: delegates.length, ARRIVED: 0, MISSING: 0, LATE: 0, ASSIGNED: 0, UNASSIGNED: 0 };
  for (const d of delegates) counts[normStatus(d.status)] = (counts[normStatus(d.status)] || 0) + 1;

  const metricHead = sum.addRow([L.keyMetrics, L.total, L.arrived, L.missing, L.late, L.assigned]);
  metricHead.eachCell((cell, col) => {
    cell.font = { bold: true, color: { argb: "FFFFFFFF" } };
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: BRAND } };
    cell.border = THIN_BORDER;
    cell.alignment = { vertical: "middle", horizontal: col === 1 ? "left" : "center" };
  });
  const metricVals = sum.addRow(["", counts.total, counts.ARRIVED, counts.MISSING, counts.LATE, counts.ASSIGNED]);
  metricVals.eachCell((cell, col) => {
    cell.border = THIN_BORDER;
    if (col > 1) { cell.alignment = { horizontal: "center" }; cell.font = { bold: true, size: 13 }; }
  });
  // Unassigned on its own line so the band stays 5 metric columns wide.
  const unRow = sum.addRow([L.unassignedNoCoach, counts.UNASSIGNED]);
  unRow.getCell(1).font = { color: { argb: "FF6B7280" } };
  unRow.getCell(2).alignment = { horizontal: "center" };
  sum.addRow([]);

  // Per-coach breakdown over the filtered set.
  const bh = sum.addRow([L.coachBreakdown, L.total, L.boarded, L.missing, L.late, L.pctBoarded]);
  bh.eachCell((cell, col) => {
    cell.font = { bold: true, color: { argb: "FFFFFFFF" } };
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: BRAND } };
    cell.border = THIN_BORDER;
    cell.alignment = { vertical: "middle", horizontal: col === 1 ? "left" : "center" };
  });
  const groups = new Map();
  for (const d of delegates) {
    const key = d.coachId || UNASSIGNED_KEY;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(d);
  }
  const coachOrder = [...coaches.map((c) => c.id), UNASSIGNED_KEY];
  for (const cid of coachOrder) {
    const list = groups.get(cid);
    if (!list || !list.length) continue;
    const total = list.length;
    const boarded = list.filter((d) => normStatus(d.status) === "ARRIVED").length;
    const missing = list.filter((d) => d.status === "MISSING").length;
    const late = list.filter((d) => d.status === "LATE").length;
    const pct = total ? Math.round((boarded / total) * 100) : 0;
    const label = cid === UNASSIGNED_KEY ? L.unassignedGroup : coachName(cid);
    const row = sum.addRow([label, total, boarded, missing, late, `${pct}%`]);
    row.eachCell((cell, col) => {
      cell.border = THIN_BORDER;
      if (col > 1) cell.alignment = { horizontal: "center" };
    });
  }

  // Best-effort; omitted if unavailable. May contain \n bullets — wrapText is
  // what makes Excel render each one as its own visible line.
  if (aiSummary) {
    sum.addRow([]);
    const aiHead = sum.addRow([L.aiSummary]);
    sum.mergeCells(aiHead.number, 1, aiHead.number, 6);
    aiHead.getCell(1).font = { bold: true, color: { argb: "FFFFFFFF" } };
    aiHead.getCell(1).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF7C3AED" } };
    const noteRow = sum.addRow([aiSummary]);
    sum.mergeCells(noteRow.number, 1, noteRow.number, 6);
    noteRow.getCell(1).alignment = { wrapText: true, vertical: "top" };
    const lineCount = aiSummary.split("\n").length;
    const charHeight = Math.ceil(aiSummary.length / 90) * 15;
    noteRow.height = Math.min(220, Math.max(26 + charHeight, lineCount * 18 + 10));
  }

  /* ===== Sheet 2 — Delegates detail ===== */
  const ws = wb.addWorksheet(L.sheetDelegates);
  const header = ws.addRow(cols.map((c) => L.columns[c.key] || c.label));
  header.font = { bold: true, color: { argb: "FFFFFFFF" } };
  header.eachCell((cell) => {
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: BRAND } };
    cell.alignment = { vertical: "middle" };
    cell.border = THIN_BORDER;
  });
  ws.views = [{ state: "frozen", ySplit: 1 }];

  // Status severity first (Missing at top), so the sheet opens on what needs
  // attention.
  const sorted = [...delegates].sort((a, b) => {
    const sa = STATUS_ORDER.indexOf(normStatus(a.status));
    const sb = STATUS_ORDER.indexOf(normStatus(b.status));
    if (sb !== sa) return sb - sa; // higher index (MISSING) first
    return (a.name || "").localeCompare(b.name || "");
  });
  // Color ONLY the Status cell, not the whole row — filling rows turned a
  // single-status sheet into one solid block with no row separation. Zebra
  // banding is independent of status, so rows stay scannable when Status is
  // monochrome for pages at a time.
  const statusIdx = cols.findIndex((c) => c.key === "status");
  const vipIdx = cols.findIndex((c) => c.key === "vip");
  sorted.forEach((d, i) => {
    const row = ws.addRow(cols.map((c) => c.get(d, ctx)));
    const band = i % 2 === 1 ? "FFF7F8FA" : null;
    row.eachCell((cell, col) => {
      cell.border = THIN_BORDER;
      if (band) cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: band } };
    });
    const fill = STATUS_FILL[normStatus(d.status)];
    if (statusIdx >= 0 && fill) {
      const cell = row.getCell(statusIdx + 1);
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: fill } };
      cell.font = { bold: true };
    }
    if (vipIdx >= 0 && d.vip) row.getCell(vipIdx + 1).font = { bold: true, color: { argb: "FFB45309" } };
  });
  ws.columns.forEach((col, i) => { col.width = cols[i]?.width || 16; });
  if (!sorted.length) ws.addRow([L.noMatch]);

  /* ===== Sheet 3 — Checkpoint history (optional, opt-in) ===== */
  if (checkpointHistory) {
    const cp = wb.addWorksheet(L.sheetCheckpoints);
    // Same filtered delegate set as the Delegates sheet — filtering to one
    // coach must not leak the whole trip's checkpoint history.
    const delegateById = new Map(delegates.map((d) => [d.id, d]));
    const rows = checkpointHistory.filter((r) => delegateById.has(r.delegateId));

    // Day/Checkpoint/Scheduled time would repeat identically on hundreds of
    // rows, so they're hoisted into one merged banner row per group instead —
    // like a pivot table's row grouping.
    const cpHeader = cp.addRow([
      L.checkpointColumns.name, L.checkpointColumns.coach, L.checkpointColumns.status,
      L.checkpointColumns.scannedBy, L.checkpointColumns.updatedAt,
    ]);
    cpHeader.font = { bold: true, color: { argb: "FFFFFFFF" } };
    cpHeader.eachCell((cell) => {
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: BRAND } };
      cell.alignment = { vertical: "middle" };
      cell.border = THIN_BORDER;
    });
    cp.views = [{ state: "frozen", ySplit: 1 }];

    // Groups rely on the query's existing chronological order (day_number,
    // sort_order, start_time): object key order is first-seen in JS, so the
    // groups need no separate sort.
    const groups = [];
    const groupIndex = new Map();
    for (const r of rows) {
      const key = `${r.dayNumber}::${r.checkpointLabel}::${r.scheduledTime}`;
      if (!groupIndex.has(key)) {
        groupIndex.set(key, groups.length);
        groups.push({ dayNumber: r.dayNumber, checkpointLabel: r.checkpointLabel, scheduledTime: r.scheduledTime, rows: [] });
      }
      groups[groupIndex.get(key)].rows.push(r);
    }

    for (const group of groups) {
      const bannerRow = cp.addRow([`${L.checkpointColumns.day} ${group.dayNumber} · ${group.checkpointLabel} · ${group.scheduledTime}`]);
      cp.mergeCells(bannerRow.number, 1, bannerRow.number, 5);
      bannerRow.getCell(1).font = { bold: true, color: { argb: "FF374151" } };
      bannerRow.getCell(1).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFE5E7EB" } };
      bannerRow.getCell(1).alignment = { vertical: "middle" };
      bannerRow.height = 20;

      // Severity-first, same convention as the Delegates sheet.
      const groupSorted = [...group.rows].sort((a, b) => {
        const sa = STATUS_ORDER.indexOf(normStatus(a.status));
        const sb = STATUS_ORDER.indexOf(normStatus(b.status));
        if (sb !== sa) return sb - sa;
        const na = delegateById.get(a.delegateId)?.name || "";
        const nb = delegateById.get(b.delegateId)?.name || "";
        return na.localeCompare(nb);
      });
      groupSorted.forEach((r, i) => {
        const d = delegateById.get(r.delegateId);
        const row = cp.addRow([
          d.name, coachName(d.coachId), L.status[normStatus(r.status)] || r.status, r.scannedBy || "", fmtDate(r.updatedAt),
        ]);
        const band = i % 2 === 1 ? "FFF7F8FA" : null;
        row.eachCell((cell) => {
          cell.border = THIN_BORDER;
          if (band) cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: band } };
        });
        const fill = STATUS_FILL[normStatus(r.status)];
        if (fill) {
          const cell = row.getCell(3); // Status column
          cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: fill } };
          cell.font = { bold: true };
        }
      });
    }
    cp.columns = [{ width: 24 }, { width: 20 }, { width: 12 }, { width: 16 }, { width: 18 }];
    if (!rows.length) cp.addRow([L.noCheckpoints]);
  }

  /* ===== Sheet 4 — Charts (optional, opt-in) =====
     PNGs of the live Analytics charts, composed client-side (title + chart +
     legend on one canvas — see frontend/src/lib/chartCapture.js) and embedded
     as real pictures, since this export is meant for a report or deck.

     Sized from the client's measurements. Extents go through `ext` (pixels),
     which is independent of row/column sizing — so a later column resize can't
     distort the pictures. */
  if (Array.isArray(chartImages) && chartImages.length) {
    const cs = wb.addWorksheet(L.sheetCharts, { views: [{ showGridLines: false }] });
    cs.getColumn(1).width = 4;
    let topRow = 1;
    for (const shot of chartImages) {
      const imageId = wb.addImage({ base64: shot.base64, extension: "png" });
      cs.addImage(imageId, {
        tl: { col: 1, row: topRow - 1 },
        ext: { width: shot.width, height: shot.height },
      });
      // ~20px per default row, plus 2 rows of gap between charts.
      topRow += Math.ceil(shot.height / 20) + 2;
    }
  }

  return wb;
}

/* ---- AI: natural language → structured filter, and export summary notes -- */
// `json` forces Ollama's structured-output mode. Required for ai-filter (must
// return a parseable {statuses,coachIds,vipOnly}) but must NOT be set for the
// prose summary — a prose prompt in JSON mode just emits "{}", which is what
// landed in the Summary sheet instead of a recap.
// `numPredict` caps generated tokens: local CPU inference scales with output
// length, and uncapped calls kept generating long after the answer was done.
// `keep_alive` keeps the model resident so a call minutes later skips the
// cold-load penalty.
async function tryOllama(prompt, { json = false, numPredict } = {}) {
  const base = process.env.OLLAMA_HOST || "http://localhost:11434";
  const model = process.env.OLLAMA_MODEL || "llama3.2";
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 30000);
  try {
    const res = await fetch(`${base}/api/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model, messages: [{ role: "user", content: prompt }], stream: false,
        keep_alive: "30m",
        ...(json ? { format: "json" } : {}),
        ...(numPredict ? { options: { num_predict: numPredict } } : {}),
      }),
      signal: controller.signal,
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data?.message?.content?.trim() || null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

async function callAnthropic(prompt, maxTokens = 400) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return null;
  const { default: Anthropic } = await import("@anthropic-ai/sdk");
  const anthropic = new Anthropic({ apiKey });
  const model = process.env.ANTHROPIC_MODEL || "claude-sonnet-4-5-20250929";
  const response = await anthropic.messages.create({ model, max_tokens: maxTokens, messages: [{ role: "user", content: prompt }] });
  return (response.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
}

// First {...} object in a model reply — chatty models wrap JSON in prose
// despite instructions.
function extractJson(text) {
  if (!text) return null;
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start < 0 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch { return null; }
}

function buildFilterPrompt(request, coaches) {
  const coachLines = coaches.map((c) => `- id "${c.id}" = ${[c.name, c.city].filter(Boolean).join(" · ")}`).join("\n");
  return `You translate a staff member's plain-language request into a JSON filter for an attendance export. Output ONLY a JSON object, no prose.

Available statuses (use these exact UPPERCASE values): UNASSIGNED, ASSIGNED, ARRIVED, LATE, MISSING.
- "arrived"/"present"/"boarded"/"checked in" → ARRIVED
- "not arrived"/"not boarded"/"still to board" → include ASSIGNED, LATE and MISSING
- "unaccounted"/"missing" → MISSING ; "late" → LATE ; "assigned"/"not yet checked in" → ASSIGNED

Available coaches:
${coachLines}
Use the exact id string. When the request names a coach by number (e.g. "coach 5", "coaches 5 to 8"), match it to the coach whose name contains that number and use that coach's id — expand ranges to every coach in them. For "unassigned"/"no coach" use "${UNASSIGNED_KEY}".

Set "vipOnly": true ONLY if the request explicitly asks for VIPs specifically (e.g. "VIPs", "VIP only", "just the VIPs", "VIP delegates"). Otherwise it MUST be false — a request about status or coach alone (e.g. "missing delegates") says nothing about VIP and must not set this.

A request for "everyone"/"all delegates"/"the whole roster" with no specific status named means NO constraint — "statuses" MUST be [], not a guessed subset of statuses.

Return this shape (use an empty array to mean "no constraint on that dimension"). ONLY put values in "statuses" or "coachIds" that the request explicitly asks for — if it doesn't mention any coach AT ALL, "coachIds" MUST be exactly [] (do NOT invent or reuse any coach id from anywhere else); if it doesn't mention a status, "statuses" MUST be []. The two examples below show one WITH a coach mentioned and one WITHOUT — copy whichever matches the actual request, don't default to a filled-in coachIds when none was asked for:
Request "missing delegates on coach 5" → {"statuses": ["MISSING"], "coachIds": ["<coach 5's real id>"], "vipOnly": false}
Request "missing delegates" (no coach mentioned) → {"statuses": ["MISSING"], "coachIds": [], "vipOnly": false}

Staff request: "${String(request).slice(0, 400)}"

JSON:`;
}

function sanitizeFilter(raw, coaches) {
  const validCoach = new Set([...coaches.map((c) => c.id), UNASSIGNED_KEY]);
  const out = { statuses: [], coachIds: [], vipOnly: false };
  if (raw && typeof raw === "object") {
    if (Array.isArray(raw.statuses)) {
      out.statuses = raw.statuses.map((s) => normStatus(String(s).toUpperCase())).filter((s) => STATUS_ORDER.includes(s));
      out.statuses = [...new Set(out.statuses)];
    }
    if (Array.isArray(raw.coachIds)) out.coachIds = raw.coachIds.filter((id) => validCoach.has(id));
    out.vipOnly = !!raw.vipOnly;
  }
  return out;
}

/* ---- routes -------------------------------------------------------------- */
// `account` restricts the export to the coaches that account can see on the
// Dashboard (getVisibleCoachIds in db/dashboard.js). Without it, a coach-scoped
// Staff account could export the whole trip's roster through this route.
async function loadTripData(idParam, account = null) {
  const tripUuid = await resolveTripUuid(idParam);
  const visibleCoachIds = await getVisibleCoachIds(tripUuid, account);
  const [trip, allDelegates, dash] = await Promise.all([getTrip(tripUuid), getDelegates(tripUuid), getDashboard(tripUuid, visibleCoachIds)]);
  const delegates = visibleCoachIds ? allDelegates.filter((d) => visibleCoachIds.has(d.coachId)) : allDelegates;
  return { tripUuid, trip, delegates, coaches: dash.coaches || [] };
}

// Fixed 3-point structure for the AI summary — must match insights.js's
// Overall/Missing/Advice shape and its zh translations exactly.
const SECTION_LABELS = {
  en: { overall: "Overall", missing: "Missing", advice: "Advice" },
  zh: { overall: "总体情况", missing: "缺席情况", advice: "建议" },
};

function buildSummaryPrompt(trip, filtered, coaches, filters, lang) {
  const labels = SECTION_LABELS[lang === "zh" ? "zh" : "en"];
  const coachName = makeCoachName(coaches, lang);
  const counts = { ARRIVED: 0, MISSING: 0, LATE: 0, ASSIGNED: 0, UNASSIGNED: 0 };
  for (const d of filtered) counts[normStatus(d.status)]++;
  const missingNames = filtered.filter((d) => d.status === "MISSING").slice(0, 12)
    .map((d) => `${d.name}${d.vip ? " (VIP)" : ""} · ${coachName(d.coachId)}`).join("; ") || "none";
  const languageInstruction = lang === "zh"
    ? "Write your entire response in Simplified Chinese (简体中文), including the three labels below exactly as given."
    : "Write your entire response in English.";

  return `You are writing an internal summary note for an SCCCI delegation attendance export, to be read by staff.

Trip: ${trip?.name || "Trip"}${trip ? `, Day ${trip.dayOf} of ${trip.totalDays}` : ""}.
This export (filters: ${describeFilters(filters, coaches, lang)}) contains ${filtered.length} delegates: ${counts.ARRIVED} arrived, ${counts.MISSING} missing, ${counts.LATE} late, ${counts.ASSIGNED} assigned, ${counts.UNASSIGNED} unassigned.
Missing delegates: ${missingNames}.

Write EXACTLY 3 numbered points, one per line, in this fixed structure:
1. ${labels.overall}: overall attendance health for this export — the specific numbers, and whether it looks on track.
2. ${labels.missing}: which delegates and/or coaches are missing, naming the ones with the most missing, and flagging any VIP delegates among them.
3. ${labels.advice}: concrete next actions staff should take right now based on this export.

Each point must start with its real number (1, 2, or 3), a period, a space, the exact label text given above, then a colon — for example the first point must literally begin "1. ${labels.overall}: " (substitute the real digit and label for points 2 and 3 the same way; never write the letter N or the word "Label" — those are not real output). Follow the label with one or two direct sentences containing specific numbers/names — no vague language. No markdown, no headers, no intro/closing sentence — just the 3 numbered points. ${languageInstruction}`;
}

// Reuses the insights provider strategy but must NEVER fail the export — any
// error just omits the notes.
async function maybeAiSummary(trip, filtered, coaches, filters, lang) {
  try {
    const prompt = buildSummaryPrompt(trip, filtered, coaches, filters, lang);
    const viaOllama = await tryOllama(prompt, { numPredict: 300 });
    if (viaOllama) return viaOllama.replace(/^```[a-z]*|```$/g, "").trim();
    return await callAnthropic(prompt, 300);
  } catch {
    return null;
  }
}

async function handleExport(req, res, filters, options) {
  const { tripUuid, trip, delegates, coaches } = await loadTripData(req.params.id, req.account);
  const filtered = delegates.filter((d) => passesFilter(d, filters));
  const lang = options.lang === "zh" ? "zh" : "en";

  const [aiSummary, checkpointHistory] = await Promise.all([
    options.includeAiSummary && filtered.length ? maybeAiSummary(trip, filtered, coaches, filters, lang) : null,
    options.includeCheckpoints ? loadCheckpointHistory(tripUuid) : null,
  ]);

  const wb = buildWorkbook({ trip, delegates: filtered, coaches, filters, columns: options.columns, aiSummary, checkpointHistory, chartImages: options.chartImages, lang });

  // Filename stays plain ASCII regardless of content language — avoids
  // Content-Disposition edge cases on older clients/OSes.
  const slug = (trip?.name || "trip").replace(/\s+/g, "_").toLowerCase();
  const fileName = `attendance_${slug}${trip ? `_day${trip.dayOf}` : ""}.xlsx`;
  res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
  res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
  await wb.xlsx.write(res);
  res.end();
}

// Primary: filtered, configurable, multi-sheet.
router.post("/api/trips/:id/export", requirePermission("exportData"), wrap(async (req, res) => {
  const body = req.body || {};
  const filters = {
    statuses: Array.isArray(body.statuses) ? body.statuses.map((s) => normStatus(String(s).toUpperCase())).filter((s) => STATUS_ORDER.includes(s)) : [],
    coachIds: Array.isArray(body.coachIds) ? body.coachIds : [],
    vipOnly: !!body.vipOnly,
  };
  const options = {
    columns: Array.isArray(body.columns) ? body.columns.filter((k) => ALL_COLUMNS.some((c) => c.key === k)) : null,
    includeAiSummary: !!body.includeAiSummary,
    includeCheckpoints: !!body.includeCheckpoints,
    // Explicit per-export choice, NOT the requester's UI language.
    lang: body.lang === "zh" ? "zh" : "en",
    chartImages: sanitizeChartImages(body.charts),
  };
  await handleExport(req, res, filters, options);
}));

/* Chart PNGs are the ONLY client-supplied binary this API accepts, so they are
 * validated, not trusted. Keep all of these checks:
 *   - must be a `data:image/png;base64,` URL — a remote URL would make the
 *     server fetch an attacker-chosen address
 *   - base64 must decode cleanly and be non-trivial
 *   - hard caps on count and per-image size, or this endpoint becomes a
 *     memory-exhaustion lever
 * Failures are DROPPED, not rejected — a malformed chart should cost one
 * picture, not the whole workbook. */
const CHART_PREFIX = "data:image/png;base64,";
const MAX_CHARTS = 12;              // more than the panel can even render
const MAX_CHART_BYTES = 4_000_000;  // ~4MB decoded; a real chart PNG is ~20-80KB
function sanitizeChartImages(input) {
  if (!Array.isArray(input)) return [];
  const out = [];
  for (const item of input.slice(0, MAX_CHARTS)) {
    if (!item || typeof item !== "object") continue;
    const url = typeof item.dataUrl === "string" ? item.dataUrl : "";
    if (!url.startsWith(CHART_PREFIX)) continue;
    const base64 = url.slice(CHART_PREFIX.length);
    if (!/^[A-Za-z0-9+/]+={0,2}$/.test(base64)) continue;
    const bytes = Math.floor((base64.length * 3) / 4);
    if (bytes < 64 || bytes > MAX_CHART_BYTES) continue;
    // Clamp the client's measurements — an absurd value produces a corrupt,
    // unopenable sheet.
    const width = Math.min(Math.max(Number(item.width) || 640, 120), 2000);
    const height = Math.min(Math.max(Number(item.height) || 360, 80), 2000);
    out.push({ base64, width, height });
  }
  return out;
}

// Back-compat: unfiltered one-click (nothing constrains any dimension).
router.get("/api/trips/:id/export", requirePermission("exportData"), wrap(async (req, res) => {
  await handleExport(req, res, { statuses: [], coachIds: [], vipOnly: false }, { columns: null, includeAiSummary: false });
}));

// Metadata for the export config modal (coach names resolved server-side).
router.get("/api/trips/:id/export/options", requireAuth(), wrap(async (req, res) => {
  const { coaches } = await loadTripData(req.params.id, req.account);
  res.json({
    columns: ALL_COLUMNS.map((c) => ({ key: c.key, label: c.label })),
    defaultColumns: DEFAULT_COLUMNS,
    statuses: STATUS_ORDER.map((s) => ({ key: s, label: T.en.status[s] })),
    coaches: coaches.map((c) => ({ id: c.id, label: [c.name, c.city].filter(Boolean).join(" · ") })),
  });
}));

// Natural language → the same filter shape the checkboxes produce, so the UI
// can show and edit it before exporting.
router.post("/api/trips/:id/export/ai-filter", requirePermission("exportData"), wrap(async (req, res) => {
  const request = (req.body?.prompt || "").toString().trim();
  if (!request) return res.status(400).json({ error: "NO_PROMPT", message: "Describe what to export." });
  const { coaches } = await loadTripData(req.params.id, req.account);
  const prompt = buildFilterPrompt(request, coaches);

  const viaOllama = await tryOllama(prompt, { json: true, numPredict: 80 });
  let parsed = extractJson(viaOllama);
  if (!parsed) {
    try {
      const viaAnthropic = await callAnthropic(prompt, 80);
      parsed = extractJson(viaAnthropic);
    } catch (err) {
      console.error("Export AI-filter call failed:", err.message || err);
    }
  }
  if (!parsed) {
    return res.status(503).json({
      error: "AI_NOT_CONFIGURED",
      message: "Natural-language filtering needs a local Ollama (free) or ANTHROPIC_API_KEY. The checkbox filters still work.",
    });
  }
  res.json({ filter: sanitizeFilter(parsed, coaches) });
}));

export default router;
